import{_ as t,o,c as n,ah as s}from"./chunks/framework.DDXs_i7t.js";const d=JSON.parse('{"title":"Screenplay Update: Scene 22 - The Emoji Lesson","description":"A surreal sequence where Helmut Horten (August Diehl) teaches a modern secretary about discretion.","frontmatter":{"title":"Screenplay Update: Scene 22 - The Emoji Lesson","description":"A surreal sequence where Helmut Horten (August Diehl) teaches a modern secretary about discretion.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/szene-emoji-lektion.md","filePath":"en/logbuch/szene-emoji-lektion.md"}'),r={name:"en/logbuch/szene-emoji-lektion.md"};function i(a,e,l,h,c,p){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="screenplay-update-scene-22-the-emoji-lesson" tabindex="-1">Screenplay Update: Scene 22 - The Emoji Lesson <a class="header-anchor" href="#screenplay-update-scene-22-the-emoji-lesson" aria-label="Permalink to &quot;Screenplay Update: Scene 22 - The Emoji Lesson&quot;">​</a></h1><p><strong>STYLE:</strong> A dreamlike sequence in which times merge. Black-and-white aesthetic meets modern smartphone lighting.</p><p><strong>CAST:</strong></p><ul><li><strong>Helmut Horten:</strong> August Diehl</li><li><strong>The Young Secretary (Schmid-type):</strong> A nervous actor in a slim-fit suit that is much too tight.</li></ul><hr><p><strong>INT. HORTEN&#39;S STUDY - NIGHT</strong></p><p>Horten (Diehl) sits at his desk. He holds a pen in his hand. In front of him stands the young secretary, hectically typing on his smartphone.</p><p><strong>HORTEN</strong> (without looking up): What are you working on there, my boy?</p><p><strong>SECRETARY</strong> (enthusiastically): I&#39;m just sending out a confirmation for the board position of the State Holding, Mr. Horten! With two rocket emojis and a bicep. People should know we&#39;re full throttle!</p><p>Horten slowly sets down the pen. The sound cuts through the room.</p><p><strong>HORTEN</strong>: Rockets? Biceps? You are leaving footprints in a swamp you will never get out of.</p><p><strong>SECRETARY</strong>: But it&#39;s encrypted! We are the family!</p><p><strong>HORTEN</strong> (stands up slowly, steps into the light): Listen to me carefully. A deal is like a good wine: it needs darkness, silence, and... no protocol. If you give a promise, give it with a handshake. If you exercise power, do it with a look. But never, do you hear, never with a yellow, laughing face in a cloud.</p><p>He steps very close to the secretary. His voice is ice-cold.</p><p><strong>HORTEN</strong>: In fifty years, people will search for my accounts and find nothing but legends. They will search for your phone clouds and find nothing but... embarrassments.</p><p><strong>FADE TO BLACK.</strong></p>',16)])])}const g=t(r,[["render",i]]);export{d as __pageData,g as default};
